/** Proves lazy in-widget playback crosses the old six-second preview limit. */
public final class InlineVideoSmoke {
    public static void run(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check)throws Exception{new InlineVideoSmoke(i,c,host,check).run();}
    /** Generated-only fixture for reviewing playback on the emulator's actual launcher. */
    public static void place(Instrumentation i,Context c,BiConsumer<Boolean,String> check)throws Exception{
        i.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
        File sample=new File(c.getCacheDir(),"launcher-video-proof.mp4");MediaSmoke.createSample(sample,12,192,108,0);ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"Nook inline launcher proof.mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");Uri uri=c.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);try(InputStream in=new FileInputStream(sample);OutputStream out=c.getContentResolver().openOutputStream(uri)){in.transferTo(out);}sample.delete();JSONObject config=Widgets.defaults("video");config.put("videoUri",uri.toString()).put("videoHideText",true).put("videoPace",1);MediaData.prepare(c,config,null);String token=java.util.UUID.randomUUID().toString();Store.pending(c,token,config);Intent callback=new Intent(c,WidgetActionReceiver.class).setAction("pinned").putExtra("token",token).setData(Uri.parse("nook://pin/"+token));PendingIntent result=PendingIntent.getBroadcast(c,0,callback,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);Bundle preview=new Bundle();preview.putParcelable(AppWidgetManager.EXTRA_APPWIDGET_PREVIEW,Widgets.render(c,-1,"video",config,false,true));check.accept(AppWidgetManager.getInstance(c).requestPinAppWidget(new ComponentName(c,Widgets.Video.class),preview,result),"Launcher accepts the generated video placement request");
    }
    private final Instrumentation i;private final Context c;private final AppWidgetHost host;private final BiConsumer<Boolean,String> check;
    private InlineVideoSmoke(Instrumentation i,Context c,AppWidgetHost host,BiConsumer<Boolean,String> check){this.i=i;this.c=c;this.host=host;this.check=check;}
    private void main(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();i.runOnMainSync(()->{try{action.run();}catch(Throwable t){error.set(t);}});if(error.get()!=null)throw new AssertionError(error.get());i.waitForIdleSync();}
    private void await(BooleanSupplier condition,int timeout,String message)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;boolean passed=false;while(!(passed=condition.getAsBoolean())&&SystemClock.elapsedRealtime()<end)Thread.sleep(100);check.accept(passed,message);}
    private static View find(View root,int id){if(root.getId()==id)return root;if(root instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),id);if(found!=null)return found;}return null;}
    private Uri sample(int w,int h,int rotation)throws Exception{File file=new File(c.getCacheDir(),"aspect-test.mp4");MediaSmoke.createSample(file,2,w,h,rotation);ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"Nook aspect test.mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");Uri uri=c.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);try(InputStream in=new FileInputStream(file);OutputStream out=c.getContentResolver().openOutputStream(uri)){in.transferTo(out);}file.delete();return uri;}
    private void run()throws Exception{
        Activity activity=null;Uri uri=null;int id=-1;JSONObject config=null;java.util.List<Uri> extra=new java.util.ArrayList<>();
        try{File source=new File(c.getCacheDir(),"inline-proof.mp4");MediaSmoke.createSample(source,12,192,108,0);File shots=new File(c.getFilesDir(),"screenshots");shots.mkdirs();java.nio.file.Files.copy(source.toPath(),new File(shots,"inline-proof.mp4").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);ContentValues values=new ContentValues();values.put(MediaStore.Video.Media.DISPLAY_NAME,"Nook inline playback test.mp4");values.put(MediaStore.Video.Media.MIME_TYPE,"video/mp4");uri=c.getContentResolver().insert(MediaStore.Video.Media.EXTERNAL_CONTENT_URI,values);try(InputStream in=new FileInputStream(source);OutputStream out=c.getContentResolver().openOutputStream(uri)){in.transferTo(out);}source.delete();config=Widgets.defaults("video");config.put("videoUri",uri.toString()).put("videoHideText",true);JSONObject metadata=MediaData.prepare(c,config,null);check.accept(metadata.optLong("duration")>11000,"Source video is longer than the old preview loop");
            activity=i.startActivitySync(new Intent(c,WidgetConfigActivity.class).putExtra("kind","video").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));i.waitForIdleSync();id=host.allocateAppWidgetId();check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(id,new ComponentName(c,Widgets.Video.class)),"Real inline widget binds");Store.config(c,id,config);Widgets.update(c,id,"video");int widget=id;Activity display=activity;AtomicReference<AppWidgetHostView> view=new AtomicReference<>();main(()->{host.startListening();AppWidgetHostView root=host.createView(c,widget,AppWidgetManager.getInstance(c).getAppWidgetInfo(widget));FrameLayout stage=new FrameLayout(display);stage.setBackgroundColor(Ui.BG);stage.addView(root,new FrameLayout.LayoutParams(Ui.dp(c,340),Ui.dp(c,300),Gravity.CENTER));display.setContentView(stage);view.set(root);});
            AdapterViewFlipper flipper=view.get().findViewById(com.nook.widgets.R.id.video_flipper);check.accept(flipper!=null,"Inline playback uses a native adapter-backed frame view");await(()->flipper.getAdapter()!=null&&flipper.getAdapter().getCount()>50,10000,"Launcher connects to the full video frame service");
            await(()->{View current=flipper.getCurrentView();if(current==null)return false;ImageView frame=(ImageView)find(current,com.nook.widgets.R.id.video_frame_image);if(frame==null||frame.getContentDescription()==null)return false;String text=frame.getContentDescription().toString();try{return Long.parseLong(text.replaceAll("[^0-9]",""))>6500&&frame.getDrawable()!=null;}catch(Exception e){return false;}},18000,"Visible widget decodes and displays source frames beyond six seconds");check.accept(InlineVideoService.lastDecodedTime(id)>6500,"Actual decoder requests reach the later part of the source");check.accept(view.get().findViewById(com.nook.widgets.R.id.video_text).getVisibility()==View.GONE,"Hide-all-text removes captions and labels");
            await(()->{View shown=flipper.getCurrentView();ImageView image=shown==null?null:(ImageView)find(shown,com.nook.widgets.R.id.video_frame_image);if(image==null||image.getContentDescription()==null)return false;try{return Long.parseLong(image.getContentDescription().toString().replaceAll("[^0-9]",""))>11000;}catch(Exception e){return false;}},8000,"Visible playback reaches the final second of the full source");await(()->flipper.getDisplayedChild()<4,4000,"The complete video loops inside the widget");
            Bitmap capture=i.getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(shots,"inline-video-proof.png"))){capture.compress(Bitmap.CompressFormat.PNG,100,out);}capture.recycle();main(()->view.get().findViewById(com.nook.widgets.R.id.widget_action1).performClick());await(()->{JSONObject root=Store.config(c,widget),state=InlineVideoState.state(c,widget,MediaData.active(root),MediaData.cached(c,root));return !state.optBoolean("playing",true);},4000,"Pause acts on the inline widget without opening a video activity");

            await(()->view.get().findViewById(com.nook.widgets.R.id.video_flipper)==null,4000,"Pausing removes the live frame adapter");
            JSONObject paused=Store.config(c,id);Bitmap frozen=MediaData.pausedFrame(c,id,paused);check.accept(frozen!=null,"Pause retains a decoded video frame");if(frozen!=null)frozen.recycle();
            for(int shape=0;shape<3;shape++){Uri item=sample(shape==0?96:160,shape==2?160:96,shape==0?0:shape==1?90:0);extra.add(item);JSONObject selection=Widgets.defaults("video");selection.put("videoUri",item.toString());JSONObject info=MediaData.prepare(c,selection,null);Class<?> expected=shape==1?Widgets.VideoPortrait.class:Widgets.VideoSquare.class;check.accept(VideoWidgets.provider(c,selection)==expected,"Source aspect chooses the matching provider, including rotation");try(VideoFrameDecoder decoder=new VideoFrameDecoder(c,item.toString())){Bitmap frame=decoder.frame(1000,320);check.accept(frame!=null,"Continuous decoder exposes an actual source frame");check.accept(frame!=null&&(shape==1?frame.getHeight()>frame.getWidth():frame.getHeight()==frame.getWidth()),"Decoded video preserves its native aspect and orientation");if(frame!=null)frame.recycle();}}
            JSONObject carousel=Store.config(c,id);VideoOptions.setVideos(c,carousel,java.util.List.of(uri.toString(),extra.get(1).toString(),extra.get(0).toString()));Store.config(c,id,carousel);InlineVideoState.reset(c,id);Widgets.update(c,id,"video");
            Instrumentation.ActivityMonitor external=i.addMonitor(VideoPlayerActivity.class.getName(),null,false);
            main(()->view.get().findViewById(com.nook.widgets.R.id.widget_action2).performClick());await(()->MediaData.videoIndex(Store.config(c,widget))==1,4000,"Real Next control changes the selected video");
            check.accept(!InlineVideoState.state(c,id,MediaData.active(Store.config(c,id)),MediaData.cached(c,Store.config(c,id))).optBoolean("playing",true),"Carousel switching preserves pause state");
            main(()->view.get().findViewById(com.nook.widgets.R.id.widget_action0).performClick());await(()->MediaData.videoIndex(Store.config(c,widget))==0,4000,"Real Previous control returns to the preceding video");main(()->view.get().findViewById(com.nook.widgets.R.id.widget_action0).performClick());await(()->MediaData.videoIndex(Store.config(c,widget))==2,4000,"Previous wraps around the carousel");
            main(()->view.get().findViewById(com.nook.widgets.R.id.widget_action1).performClick());await(()->InlineVideoState.state(c,widget,MediaData.active(Store.config(c,widget)),MediaData.cached(c,Store.config(c,widget))).optBoolean("playing",false),4000,"Play resumes inside the widget");check.accept(external.getHits()==0,"Inline transport never opens the external video activity");i.removeMonitor(external);
            JSONObject hub=Widgets.defaults("universal");hub.put("page","video").put("pages",new JSONObject().put("video",new JSONObject(carousel.toString()).put("videoHideText",true).put("videoPaused",false)));int hubId=host.allocateAppWidgetId();try{check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(hubId,new ComponentName(c,Widgets.Universal.class)),"Universal video binds through Android");Store.config(c,hubId,hub);Widgets.update(c,hubId,"universal");main(()->{AppWidgetHostView root=host.createView(c,hubId,AppWidgetManager.getInstance(c).getAppWidgetInfo(hubId));FrameLayout stage=new FrameLayout(display);stage.addView(root,new FrameLayout.LayoutParams(Ui.dp(c,340),Ui.dp(c,400),Gravity.CENTER));display.setContentView(stage);view.set(root);});await(()->{AdapterViewFlipper frames=view.get().findViewById(com.nook.widgets.R.id.video_flipper);if(frames==null||frames.getCurrentView()==null)return false;ImageView image=(ImageView)find(frames.getCurrentView(),com.nook.widgets.R.id.video_frame_image);return image!=null&&image.getContentDescription()!=null&&image.getDrawable()!=null;},10000,"Full video also displays real frames inside Universal");check.accept(view.get().findViewById(com.nook.widgets.R.id.hub_label).getVisibility()==View.GONE&&((TextView)view.get().findViewById(com.nook.widgets.R.id.hub_count)).getText().length()==0,"Hide-all-text also removes Universal captions");main(()->view.get().findViewById(com.nook.widgets.R.id.widget_action2).performClick());await(()->MediaData.videoIndex(UniversalWidget.pageSettings(Store.config(c,hubId),"video"))==1,4000,"Universal carousel changes its own nested video selection");check.accept(MediaData.videoIndex(Store.config(c,widget))==2,"Different widget copies retain independent carousels");UniversalWidget.switchPage(c,hubId,"menu");check.accept(!UniversalWidget.currentPage(Store.config(c,hubId)).equals("video"),"Leaving Universal video returns to its other tools");}finally{host.deleteAppWidgetId(hubId);Store.removeConfig(c,hubId);InlineVideoState.reset(c,hubId);}
            JSONObject legacy=Widgets.defaults("video");legacy.put("videoUri",uri.toString());check.accept(MediaData.videos(legacy).size()==1,"Existing single-video widgets remain compatible");JSONObject lateStart=new JSONObject(legacy.toString()).put("clipStart",600);check.accept(MediaData.prepare(c,lateStart,null).optLong("duration")>11000,"Full-video mode ignores short-loop start limits");JSONObject before=new JSONObject(carousel.toString());check.accept(!VideoOptions.picked(display,carousel,70,Activity.RESULT_CANCELED,null)&&before.toString().equals(carousel.toString()),"Canceling multi-selection preserves the carousel");
            for(Class<?> provider:new Class<?>[]{Widgets.VideoPortrait.class,Widgets.VideoSquare.class}){int alias=host.allocateAppWidgetId();check.accept(AppWidgetManager.getInstance(c).bindAppWidgetIdIfAllowed(alias,new ComponentName(c,provider)),"Aspect-specific provider binds through Android");check.accept(Widgets.kindOf(AppWidgetManager.getInstance(c).getAppWidgetInfo(alias).provider).equals("video"),"Aspect-specific provider retains video configuration");host.deleteAppWidgetId(alias);}
        }finally{main(host::stopListening);if(activity!=null){Activity done=activity;main(done::finish);}if(id>0){host.deleteAppWidgetId(id);Store.removeConfig(c,id);InlineVideoState.reset(c,id);}if(uri!=null)c.getContentResolver().delete(uri,null,null);for(Uri item:extra)c.getContentResolver().delete(item,null,null);}
    }
}
